const fixSpaces = (text) => {
    var index = 0;
	var space_index = 0;
	var substring = "";
	while(index < text.length){
		space_index = text.indexOf(" ", index);
		if(space_index == -1){
			substring = text.substring(index, text.length);
			substring = substring.replace(/ /g, "_");
			text = text.substring(0, index) + substring;
			break;
		}
		substring = text.substring(index, space_index);
		substring = substring.replace(/ /g, "_");
		text = text.substring(0, index) + substring + text.substring(space_index);
		index = space_index + 1;
	}
	return text.replace(/\s+/g, "-");
}

