      arr.push(String.fromCharCode(char + 2));
    }
    //if that letter is the letter 'z' we want to push the character code of the letter 'b' to the array instead
    else if(char === 122){
      arr.push(String.fromCharCode(98));
    }
    //if that letter is the letter 'y' we want to push the character code of the letter 'a' to the array instead
    else if(char === 121){
      arr.push(String.fromCharCode(97));
    }
  }
  //now we loop through the length of the array and assign each letter to the string
  for(let i = 0; i < arr.length; i++){
    str += arr[i];
  }
  //now we return the string
  return str;
}

