const addElements = (arr, k) => {
    let count = 0;
  let i = 0;
  while(i < arr.length && count < k){
    if(arr[i] > 9 && arr[i] < 100){
      count++;
    }
    i++;
  }
  return arr.slice(0,i).reduce((a,b) => {
    if(b > 9 && b < 100){
      return a + b;
    }
    return a;
  }, 0);
}

