    // make a copy of the list
    let lst_ = lst.slice();
    for (let i = 0; i < lst_.length; i++){
        // check if the index is a multiple of 3
        if ((i+1) % 3 == 0){
            // square it 
            lst_[i] = lst_[i] * lst_[i];
        }
        // check if the index is a multiple of 4
        if ((i+1) % 4 == 0){
            // cube it
            lst_[i] = lst_[i] * lst_[i] * lst_[i];
        }
    }
    // sum up the list
    let sum = 0;
    for (let i = 0; i < lst_.length; i++){
        sum += lst_[i];
    }
    return sum;
}

