  var mostOccurrences = 0;
  //loop through object
  for(var key in obj){
    //check to see if the value is greater than the most occurrences
    if(obj[key] > mostOccurrences){
      //if it is replace the most occurrences
      mostOccurrences = obj[key];
    }
  }
  //create a new object
  var newObj = {};
  //loop through object
  for(var keys in obj){
    //check to see if the value is equal to the most occurrences
    if(obj[keys] === mostOccurrences){
      //if it is add the key and value to the new object
      newObj[keys] = obj[keys];
    }
  }
  //return new object
  return newObj;
}

